export class Disposable {
  constructor(callOnDispose: () => void);
  static from(...disposables: { dispose(): void }[]): Disposable;
  dispose(): void;
}

export interface CancellationToken {
  isCancellationRequested: boolean;
  onCancellationRequested(listener: () => void): Disposable;
}

export class CancellationTokenSource implements Disposable {
  readonly token: CancellationToken;
  cancel(): void;
  dispose(): void;
}

export type Event<T> = (listener: (e: T) => unknown, thisArgs?: unknown, disposables?: Disposable[]) => Disposable;

export class EventEmitter<T> implements Disposable {
  readonly event: Event<T>;
  fire(data: T): void;
  dispose(): void;
}

export class Uri {
  readonly scheme: string;
  readonly authority: string;
  readonly path: string;
  readonly query: string;
  readonly fragment: string;
  readonly fsPath: string;
  static file(path: string): Uri;
  static parse(value: string): Uri;
  static joinPath(base: Uri, ...pathSegments: string[]): Uri;
  with(change: { scheme?: string; authority?: string; path?: string; query?: string; fragment?: string }): Uri;
  toString(skipEncoding?: boolean): string;
}

export class Position {
  readonly line: number;
  readonly character: number;
  constructor(line: number, character: number);
  isBefore(other: Position): boolean;
  isBeforeOrEqual(other: Position): boolean;
  isAfter(other: Position): boolean;
  isAfterOrEqual(other: Position): boolean;
  isEqual(other: Position): boolean;
  translate(lineDelta?: number, characterDelta?: number): Position;
  with(line?: number, character?: number): Position;
}

export class Range {
  readonly start: Position;
  readonly end: Position;
  readonly isEmpty: boolean;
  constructor(start: Position, end: Position);
  constructor(startLine: number, startCharacter: number, endLine: number, endCharacter: number);
  contains(positionOrRange: Position | Range): boolean;
}

export class Selection extends Range {
  readonly anchor: Position;
  readonly active: Position;
  constructor(anchor: Position, active: Position);
}

export class Location {
  uri: Uri;
  range: Range;
  constructor(uri: Uri, rangeOrPosition: Range | Position);
}

export class TextEdit {
  range: Range;
  newText: string;
  constructor(range: Range, newText: string);
  static replace(range: Range, newText: string): TextEdit;
  static insert(position: Position, newText: string): TextEdit;
  static delete(range: Range): TextEdit;
}

export class WorkspaceEdit {
  replace(uri: Uri, range: Range, newText: string): void;
  insert(uri: Uri, position: Position, newText: string): void;
  delete(uri: Uri, range: Range): void;
  renameFile(oldUri: Uri, newUri: Uri, options?: { overwrite?: boolean; ignoreIfExists?: boolean }): void;
  deleteFile(uri: Uri, options?: { recursive?: boolean; ignoreIfNotExists?: boolean; useTrash?: boolean }): void;
  createFile(uri: Uri, options?: { overwrite?: boolean; ignoreIfExists?: boolean }): void;
  get(uri: Uri): TextEdit[];
  entries(): [Uri, TextEdit[]][];
  readonly size: number;
}

export enum CompletionItemKind {
  Text = 0,
  Method = 1,
  Function = 2,
  Constructor = 3,
  Field = 4,
  Variable = 5,
  Class = 6,
  Interface = 7,
  Module = 8,
  Property = 9,
  Unit = 10,
  Value = 11,
  Enum = 12,
  Keyword = 13,
  Snippet = 14,
  Color = 15,
  File = 16,
  Reference = 17,
  Folder = 18,
  EnumMember = 19,
  Constant = 20,
  Struct = 21,
  Event = 22,
  Operator = 23,
  TypeParameter = 24,
}

export class SnippetString {
  value: string;
  constructor(value?: string);
}

export class MarkdownString {
  value: string;
  isTrusted?: boolean;
  constructor(value?: string);
  appendMarkdown(value: string): MarkdownString;
  appendCodeblock(value: string, language?: string): MarkdownString;
}

export class CompletionItem {
  label: string;
  kind?: CompletionItemKind;
  detail?: string;
  documentation?: string | MarkdownString;
  insertText?: string | SnippetString;
  range?: Range;
  sortText?: string;
  filterText?: string;
  commitCharacters?: string[];
  constructor(label: string, kind?: CompletionItemKind);
}

export class CompletionList {
  isIncomplete: boolean;
  items: CompletionItem[];
  constructor(items?: CompletionItem[], isIncomplete?: boolean);
}

export class Hover {
  contents: (MarkdownString | string)[];
  range?: Range;
  constructor(contents: MarkdownString | string | (MarkdownString | string)[], range?: Range);
}

export interface Command {
  title: string;
  command: string;
  tooltip?: string;
  arguments?: unknown[];
}

export class CodeLens {
  range: Range;
  command?: Command;
  readonly isResolved: boolean;
  constructor(range: Range, command?: Command);
}

export class CodeActionKind {
  static readonly QuickFix: CodeActionKind;
  static readonly Refactor: CodeActionKind;
  static readonly RefactorExtract: CodeActionKind;
  static readonly Source: CodeActionKind;
  readonly value: string;
}

export class CodeAction {
  title: string;
  kind?: CodeActionKind;
  edit?: WorkspaceEdit;
  command?: Command;
  constructor(title: string, kind?: CodeActionKind);
}

export enum DiagnosticSeverity {
  Error = 0,
  Warning = 1,
  Information = 2,
  Hint = 3,
}

export class Diagnostic {
  range: Range;
  message: string;
  severity: DiagnosticSeverity;
  code?: string | number;
  source?: string;
  constructor(range: Range, message: string, severity?: DiagnosticSeverity);
}

export enum StatusBarAlignment {
  Left = 1,
  Right = 2,
}

export enum FileType {
  Unknown = 0,
  File = 1,
  Directory = 2,
  SymbolicLink = 64,
}

export enum ExtensionMode {
  Production = 1,
  Development = 2,
  Test = 3,
}

export class RelativePattern {
  baseUri: Uri;
  pattern: string;
  constructor(base: WorkspaceFolder | Uri | string, pattern: string);
}

export interface TextLine {
  readonly lineNumber: number;
  readonly text: string;
  readonly range: Range;
  readonly firstNonWhitespaceCharacterIndex: number;
  readonly isEmptyOrWhitespace: boolean;
}

export interface TextDocument {
  readonly uri: Uri;
  readonly fileName: string;
  readonly languageId: string;
  readonly version: number;
  readonly isDirty: boolean;
  readonly isUntitled: boolean;
  readonly lineCount: number;
  getText(range?: Range): string;
  lineAt(line: number | Position): TextLine;
  offsetAt(position: Position): number;
  positionAt(offset: number): Position;
  getWordRangeAtPosition(position: Position, regex?: RegExp): Range | undefined;
  save(): Promise<boolean>;
}

export interface TextEditor {
  readonly document: TextDocument;
  selection: Selection;
}

export interface WorkspaceFolder {
  readonly uri: Uri;
  readonly name: string;
  readonly index: number;
}

export interface ExtensionContext {
  readonly subscriptions: { dispose(): void }[];
  readonly extensionPath: string;
  readonly extensionUri: Uri;
  readonly globalStorageUri: Uri;
  readonly storageUri?: Uri;
  readonly extensionMode: ExtensionMode;
  asAbsolutePath(relativePath: string): string;
}

export interface StatusBarItem extends Disposable {
  readonly alignment: StatusBarAlignment;
  readonly priority?: number;
  text: string;
  tooltip?: string;
  command?: string | Command;
  show(): void;
  hide(): void;
}

export interface OutputChannel extends Disposable {
  readonly name: string;
  append(value: string): void;
  appendLine(value: string): void;
  clear(): void;
  show(preserveFocus?: boolean): void;
}

export interface FileSystemWatcher extends Disposable {
  readonly onDidCreate: Event<Uri>;
  readonly onDidChange: Event<Uri>;
  readonly onDidDelete: Event<Uri>;
}

export interface CompletionItemProvider {
  provideCompletionItems(
    document: TextDocument,
    position: Position,
    token: CancellationToken,
    context: { triggerKind: number; triggerCharacter?: string },
  ): CompletionItem[] | CompletionList | Promise<CompletionItem[] | CompletionList | null | undefined> | null | undefined;
}

export interface CodeLensProvider {
  provideCodeLenses(document: TextDocument, token: CancellationToken): CodeLens[] | Promise<CodeLens[]>;
  resolveCodeLens?(codeLens: CodeLens, token: CancellationToken): CodeLens | Promise<CodeLens>;
}

export type DocumentSelector = string | { language?: string; scheme?: string; pattern?: string } | Array<string | { language?: string; scheme?: string; pattern?: string }>;

export interface WorkspaceConfiguration {
  get<T>(section: string): T | undefined;
  get<T>(section: string, defaultValue: T): T;
  has(section: string): boolean;
  update(section: string, value: unknown): Promise<void>;
}

export interface QuickPickItem {
  label: string;
  description?: string;
  detail?: string;
  picked?: boolean;
  alwaysShow?: boolean;
}

export interface FileWillRenameEvent {
  readonly files: readonly { readonly oldUri: Uri; readonly newUri: Uri }[];
  waitUntil(thenable: Promise<WorkspaceEdit | unknown>): void;
}

export interface FileWillDeleteEvent {
  readonly files: readonly Uri[];
  waitUntil(thenable: Promise<WorkspaceEdit | unknown>): void;
}

export interface FileWillCreateEvent {
  readonly files: readonly Uri[];
  waitUntil(thenable: Promise<WorkspaceEdit | unknown>): void;
}

export interface TextDocumentShowOptions {
  selection?: Range;
  preview?: boolean;
  preserveFocus?: boolean;
}

export const workspace: {
  workspaceFolders: readonly WorkspaceFolder[] | undefined;
  readonly textDocuments: readonly TextDocument[];
  readonly fs: {
    readFile(uri: Uri): Promise<Uint8Array>;
    writeFile(uri: Uri, content: Uint8Array): Promise<void>;
    stat(uri: Uri): Promise<{ type: FileType; ctime: number; mtime: number; size: number }>;
    delete(uri: Uri, options?: { recursive?: boolean }): Promise<void>;
    rename(source: Uri, target: Uri, options?: { overwrite?: boolean }): Promise<void>;
    readDirectory(uri: Uri): Promise<[string, FileType][]>;
  };
  findFiles(include: string | RelativePattern, exclude?: string | RelativePattern | null): Promise<Uri[]>;
  openTextDocument(uri: Uri | string): Promise<TextDocument>;
  createFileSystemWatcher(globPattern: string | RelativePattern): FileSystemWatcher;
  getConfiguration(section?: string): WorkspaceConfiguration;
  applyEdit(edit: WorkspaceEdit): Promise<boolean>;
  readonly onDidChangeConfiguration: Event<{ affectsConfiguration(section: string): boolean }>;
  readonly onDidCreateFiles: Event<{ readonly files: readonly Uri[] }>;
  readonly onDidDeleteFiles: Event<{ readonly files: readonly Uri[] }>;
  readonly onDidRenameFiles: Event<{ readonly files: readonly { oldUri: Uri; newUri: Uri }[] }>;
  readonly onWillCreateFiles: Event<FileWillCreateEvent>;
  readonly onWillDeleteFiles: Event<FileWillDeleteEvent>;
  readonly onWillRenameFiles: Event<FileWillRenameEvent>;
  readonly onDidSaveTextDocument: Event<TextDocument>;
  readonly onDidChangeTextDocument: Event<{ readonly document: TextDocument }>;
  readonly onDidOpenTextDocument: Event<TextDocument>;
};

export const window: {
  activeTextEditor: TextEditor | undefined;
  readonly onDidChangeActiveTextEditor: Event<TextEditor | undefined>;
  showInformationMessage(message: string, ...items: string[]): Promise<string | undefined>;
  showWarningMessage(message: string, ...items: string[]): Promise<string | undefined>;
  showErrorMessage(message: string, ...items: string[]): Promise<string | undefined>;
  showQuickPick<T extends QuickPickItem>(items: readonly T[] | Promise<readonly T[]>, options?: { canPickMany?: boolean; placeHolder?: string }): Promise<T | T[] | undefined>;
  showQuickPick(items: readonly string[] | Promise<readonly string[]>, options?: { canPickMany?: boolean; placeHolder?: string }): Promise<string | string[] | undefined>;
  showTextDocument(document: TextDocument | Uri, options?: TextDocumentShowOptions): Promise<TextEditor>;
  createOutputChannel(name: string): OutputChannel;
  createStatusBarItem(alignment?: StatusBarAlignment, priority?: number): StatusBarItem;
};

export const languages: {
  registerCompletionItemProvider(selector: DocumentSelector, provider: CompletionItemProvider, ...triggerCharacters: string[]): Disposable;
  registerCodeLensProvider(selector: DocumentSelector, provider: CodeLensProvider): Disposable;
  registerDefinitionProvider(selector: DocumentSelector, provider: unknown): Disposable;
  registerHoverProvider(selector: DocumentSelector, provider: unknown): Disposable;
  registerCodeActionsProvider(selector: DocumentSelector, provider: unknown): Disposable;
  createDiagnosticCollection(name?: string): {
    readonly name: string;
    set(uri: Uri, diagnostics: readonly Diagnostic[] | undefined): void;
    delete(uri: Uri): void;
    clear(): void;
    get(uri: Uri): readonly Diagnostic[];
    dispose(): void;
  };
};

export const commands: {
  registerCommand(command: string, callback: (...args: unknown[]) => unknown): Disposable;
  executeCommand<T = unknown>(command: string, ...rest: unknown[]): Promise<T>;
  getCommands(filterInternal?: boolean): Promise<string[]>;
};

export const __mock: {
  createTextDocument(uri: Uri, text: string, languageId?: string): TextDocument;
  configStore: Map<string, unknown>;
  commandHandlers: Map<string, (...args: unknown[]) => unknown>;
  registeredProviders: Array<{ type: string; selector: unknown; provider: unknown; triggerChars?: string[] }>;
  emitters: Record<string, EventEmitter<unknown>>;
  reset(): void;
};
